(function(){"use strict";if(document.readyState!=="loading"){throw new Error("Blogger embed must load synchronously during HTML parsing");}document.write("<div id=\"ocdGraduationResultPage\">\n\n<style>\n/* =========================================================\n   OCD - K\u1ebeT QU\u1ea2 T\u1ed0T NGHI\u1ec6P\n   GRADUATION RESULT v1.0\n\n   DATA:\n   - NopBaiLuyenTap\n   - BaiThiTotNghiep\n   - ChamThiTotNghiep\n\n   C\u01a0 CH\u1ebe:\n   - Gh\u00e9p b\u1eb1ng Exam ID\n   - LT 50%\n   - TH 50%\n   - \u0110i\u1ec3m cu\u1ed1i = (LT + TH) / 2\n   - >= 7: \u0110\u1ea0T\n   - < 7: KH\u00d4NG \u0110\u1ea0T\n========================================================= */\n\n\n/* =========================================================\n   ROOT\n========================================================= */\n\n#ocdGraduationResultPage{\n    --paper:#fffdf8;\n    --paper2:#f7f1e7;\n\n    --ink:#302923;\n    --muted:#786f66;\n    --line:#e3d7c7;\n\n    --brown:#765344;\n    --brown-dark:#51372d;\n\n    --gold:#aa7a35;\n\n    --green:#397153;\n    --green-soft:#eaf5ee;\n\n    --red:#963b3b;\n    --red-soft:#faeaea;\n\n    --orange:#a66d25;\n    --orange-soft:#fff1d7;\n\n    max-width:1100px;\n\n    margin:24px auto 60px;\n\n    padding:0 12px;\n\n    font-family:\n        Arial,\n        Helvetica,\n        sans-serif;\n\n    color:var(--ink);\n\n    line-height:1.6;\n}\n\n#ocdGraduationResultPage *{\n    box-sizing:border-box;\n}\n\n\n/* =========================================================\n   HERO\n========================================================= */\n\n.gr-hero{\n    position:relative;\n\n    overflow:hidden;\n\n    padding:40px 24px;\n\n    border:1px solid #dcc48d;\n    border-radius:22px;\n\n    background:\n        radial-gradient(\n            circle at 10% 15%,\n            rgba(181,135,69,.18),\n            transparent 30%\n        ),\n        radial-gradient(\n            circle at 90% 85%,\n            rgba(118,83,68,.11),\n            transparent 35%\n        ),\n        linear-gradient(\n            135deg,\n            #fff7e6,\n            #fffdf8\n        );\n\n    text-align:center;\n\n    box-shadow:\n        0 12px 35px\n        rgba(55,40,28,.08);\n}\n\n.gr-hero-badge{\n    display:inline-block;\n\n    padding:6px 14px;\n\n    margin-bottom:11px;\n\n    border:1px solid #ddc48c;\n    border-radius:999px;\n\n    background:#fff8e5;\n\n    color:#805c27;\n\n    font-size:12px;\n    font-weight:900;\n}\n\n.gr-hero h1{\n    margin:0;\n\n    font-family:Georgia,serif;\n\n    font-size:35px;\n\n    color:var(--brown-dark);\n}\n\n.gr-hero p{\n    max-width:740px;\n\n    margin:10px auto 0;\n\n    color:var(--muted);\n}\n\n.gr-rule{\n    display:inline-flex;\n\n    margin-top:16px;\n\n    padding:8px 14px;\n\n    border-radius:999px;\n\n    background:#f5ead7;\n\n    color:#755427;\n\n    font-size:12px;\n    font-weight:900;\n}\n\n\n/* =========================================================\n   CARD\n========================================================= */\n\n.gr-card{\n    margin-top:18px;\n\n    padding:22px;\n\n    border:1px solid var(--line);\n    border-radius:18px;\n\n    background:#fff;\n\n    box-shadow:\n        0 8px 25px\n        rgba(55,40,28,.055);\n}\n\n.gr-card-title{\n    margin:0 0 14px;\n\n    font-family:Georgia,serif;\n\n    font-size:21px;\n\n    color:var(--brown-dark);\n}\n\n\n/* =========================================================\n   LOOKUP\n========================================================= */\n\n.gr-search-row{\n    display:flex;\n\n    gap:10px;\n}\n\n.gr-input{\n    width:100%;\n    min-height:48px;\n\n    padding:10px 14px;\n\n    border:1px solid #d9cbb8;\n    border-radius:11px;\n\n    background:#fff;\n\n    color:var(--ink);\n\n    font-size:15px;\n\n    outline:none;\n}\n\n.gr-input:focus{\n    border-color:#ae8450;\n\n    box-shadow:\n        0 0 0 3px\n        rgba(174,132,80,.12);\n}\n\n\n/* =========================================================\n   BUTTON\n========================================================= */\n\n.gr-btn{\n    min-height:44px;\n\n    padding:9px 17px;\n\n    border:0;\n    border-radius:11px;\n\n    background:var(--brown);\n\n    color:#fff;\n\n    font-size:13px;\n    font-weight:900;\n\n    cursor:pointer !important;\n    pointer-events:auto !important;\n}\n\n.gr-btn.secondary{\n    border:1px solid #d7c8b6;\n\n    background:#fff;\n\n    color:var(--brown-dark);\n}\n\n.gr-btn:disabled{\n    opacity:.45;\n\n    cursor:not-allowed !important;\n}\n\n\n/* =========================================================\n   MESSAGE\n========================================================= */\n\n.gr-message{\n    display:none;\n\n    margin-top:12px;\n\n    padding:11px 13px;\n\n    border-radius:10px;\n\n    font-size:13px;\n    font-weight:700;\n}\n\n.gr-message.show{\n    display:block;\n}\n\n.gr-message.loading{\n    background:#f4eee5;\n\n    color:#745c44;\n}\n\n.gr-message.success{\n    background:var(--green-soft);\n\n    color:#316446;\n}\n\n.gr-message.error{\n    background:var(--red-soft);\n\n    color:#8b3838;\n}\n\n\n/* =========================================================\n   EXAM ATTEMPT LIST\n========================================================= */\n\n.gr-attempt-list{\n    display:grid;\n\n    gap:10px;\n\n    margin-top:15px;\n}\n\n.gr-attempt{\n    display:grid;\n\n    grid-template-columns:\n        minmax(0,1fr)\n        auto;\n\n    align-items:center;\n\n    gap:12px;\n\n    padding:14px;\n\n    border:1px solid var(--line);\n    border-radius:12px;\n\n    background:var(--paper);\n}\n\n.gr-attempt-name{\n    color:var(--brown-dark);\n\n    font-weight:900;\n}\n\n.gr-attempt-meta{\n    margin-top:4px;\n\n    color:var(--muted);\n\n    font-size:12px;\n}\n\n.gr-attempt-status{\n    display:inline-block;\n\n    margin-top:6px;\n\n    padding:4px 8px;\n\n    border-radius:999px;\n\n    font-size:10px;\n    font-weight:900;\n}\n\n.gr-attempt-status.graded{\n    background:var(--green-soft);\n\n    color:var(--green);\n}\n\n.gr-attempt-status.waiting{\n    background:var(--orange-soft);\n\n    color:var(--orange);\n}\n\n\n/* =========================================================\n   PROFILE\n========================================================= */\n\n.gr-profile-grid{\n    display:grid;\n\n    grid-template-columns:\n        repeat(4,minmax(0,1fr));\n\n    gap:10px;\n}\n\n.gr-info{\n    padding:12px;\n\n    border:1px solid var(--line);\n    border-radius:12px;\n\n    background:var(--paper);\n}\n\n.gr-info-label{\n    color:var(--muted);\n\n    font-size:10px;\n    font-weight:900;\n\n    text-transform:uppercase;\n}\n\n.gr-info-value{\n    margin-top:4px;\n\n    color:var(--brown-dark);\n\n    font-size:15px;\n    font-weight:900;\n\n    overflow-wrap:anywhere;\n}\n\n\n/* =========================================================\n   WAITING\n========================================================= */\n\n.gr-waiting{\n    margin-top:18px;\n\n    padding:22px;\n\n    border:1px solid #ead6aa;\n    border-radius:15px;\n\n    background:#fff7e8;\n\n    text-align:center;\n}\n\n.gr-waiting-icon{\n    display:flex;\n\n    width:62px;\n    height:62px;\n\n    margin:0 auto 10px;\n\n    align-items:center;\n    justify-content:center;\n\n    border-radius:50%;\n\n    background:#f5e6c9;\n\n    color:#956827;\n\n    font-size:28px;\n    font-weight:900;\n}\n\n.gr-waiting-title{\n    color:#765526;\n\n    font-family:Georgia,serif;\n\n    font-size:20px;\n    font-weight:900;\n}\n\n.gr-waiting-text{\n    margin-top:5px;\n\n    color:#816e57;\n\n    font-size:13px;\n}\n\n\n/* =========================================================\n   RESULT HERO\n========================================================= */\n\n.gr-result-hero{\n    margin-top:18px;\n\n    padding:28px 20px;\n\n    border-radius:18px;\n\n    text-align:center;\n}\n\n.gr-result-hero.pass{\n    border:1px solid #a9ccb6;\n\n    background:\n        linear-gradient(\n            135deg,\n            #edf8f0,\n            #fafffb\n        );\n}\n\n.gr-result-hero.fail{\n    border:1px solid #e1b2b2;\n\n    background:\n        linear-gradient(\n            135deg,\n            #fceded,\n            #fffafa\n        );\n}\n\n.gr-result-icon{\n    display:flex;\n\n    width:72px;\n    height:72px;\n\n    margin:0 auto 11px;\n\n    align-items:center;\n    justify-content:center;\n\n    border-radius:50%;\n\n    font-size:31px;\n    font-weight:900;\n}\n\n.pass .gr-result-icon{\n    background:#d8ecdf;\n\n    color:var(--green);\n}\n\n.fail .gr-result-icon{\n    background:#f2dada;\n\n    color:var(--red);\n}\n\n.gr-result-label{\n    font-size:12px;\n    font-weight:900;\n\n    letter-spacing:.05em;\n}\n\n.pass .gr-result-label{\n    color:var(--green);\n}\n\n.fail .gr-result-label{\n    color:var(--red);\n}\n\n.gr-final-score{\n    margin-top:3px;\n\n    font-family:Georgia,serif;\n\n    font-size:54px;\n    font-weight:900;\n\n    line-height:1.05;\n\n    color:var(--brown-dark);\n}\n\n.gr-final-status{\n    margin-top:8px;\n\n    font-family:Georgia,serif;\n\n    font-size:27px;\n    font-weight:900;\n}\n\n.pass .gr-final-status{\n    color:var(--green);\n}\n\n.fail .gr-final-status{\n    color:var(--red);\n}\n\n\n/* =========================================================\n   SCORE GRID\n========================================================= */\n\n.gr-score-grid{\n    display:grid;\n\n    grid-template-columns:\n        repeat(3,minmax(0,1fr));\n\n    gap:10px;\n\n    margin-top:18px;\n}\n\n.gr-score-box{\n    padding:16px;\n\n    border:1px solid var(--line);\n    border-radius:13px;\n\n    background:var(--paper);\n\n    text-align:center;\n}\n\n.gr-score-number{\n    color:var(--brown-dark);\n\n    font-size:28px;\n    font-weight:900;\n}\n\n.gr-score-label{\n    color:var(--muted);\n\n    font-size:11px;\n}\n\n\n/* =========================================================\n   FORMULA\n========================================================= */\n\n.gr-formula{\n    margin-top:14px;\n\n    padding:13px;\n\n    border:1px dashed #d8c8b4;\n    border-radius:11px;\n\n    background:#fffaf2;\n\n    color:#705a45;\n\n    text-align:center;\n\n    font-size:13px;\n}\n\n.gr-formula strong{\n    color:var(--brown-dark);\n}\n\n\n/* =========================================================\n   PRACTICAL RESULTS\n========================================================= */\n\n.gr-section-head{\n    display:flex;\n\n    align-items:center;\n    justify-content:space-between;\n\n    gap:10px;\n\n    margin-top:23px;\n    margin-bottom:11px;\n}\n\n.gr-section-title{\n    margin:0;\n\n    font-family:Georgia,serif;\n\n    font-size:20px;\n\n    color:var(--brown-dark);\n}\n\n.gr-practical-grid{\n    display:grid;\n\n    grid-template-columns:\n        repeat(2,minmax(0,1fr));\n\n    gap:12px;\n}\n\n.gr-practical{\n    overflow:hidden;\n\n    border:1px solid var(--line);\n    border-radius:14px;\n\n    background:#fff;\n}\n\n.gr-practical-image-wrap{\n    aspect-ratio:4/3;\n\n    overflow:hidden;\n\n    background:#f2ede7;\n}\n\n.gr-practical-image{\n    display:block;\n\n    width:100%;\n    height:100%;\n\n    object-fit:contain;\n}\n\n.gr-no-image{\n    display:flex;\n\n    width:100%;\n    height:100%;\n\n    align-items:center;\n    justify-content:center;\n\n    padding:20px;\n\n    color:var(--muted);\n\n    text-align:center;\n}\n\n.gr-practical-body{\n    padding:13px;\n}\n\n.gr-practical-question{\n    color:#966c34;\n\n    font-size:11px;\n    font-weight:900;\n}\n\n.gr-practical-title{\n    margin-top:3px;\n\n    color:var(--brown-dark);\n\n    font-size:15px;\n    font-weight:900;\n}\n\n.gr-practical-note{\n    margin-top:5px;\n\n    color:var(--muted);\n\n    font-size:12px;\n}\n\n.gr-practical-scores{\n    display:grid;\n\n    grid-template-columns:\n        repeat(2,1fr);\n\n    gap:7px;\n\n    margin-top:10px;\n}\n\n.gr-small-score{\n    padding:8px;\n\n    border-radius:9px;\n\n    background:#f6f0e7;\n\n    text-align:center;\n}\n\n.gr-small-score-label{\n    color:var(--muted);\n\n    font-size:9px;\n    font-weight:900;\n\n    text-transform:uppercase;\n}\n\n.gr-small-score-value{\n    margin-top:2px;\n\n    color:var(--brown-dark);\n\n    font-size:18px;\n    font-weight:900;\n}\n\n.gr-comment{\n    margin-top:9px;\n\n    padding:10px;\n\n    border-radius:9px;\n\n    background:#f8f4ee;\n\n    color:#66594d;\n\n    font-size:12px;\n}\n\n\n/* =========================================================\n   EXAMINER\n========================================================= */\n\n.gr-examiner{\n    margin-top:18px;\n\n    padding:14px;\n\n    border:1px solid var(--line);\n    border-radius:12px;\n\n    background:#fffaf2;\n}\n\n.gr-examiner-grid{\n    display:grid;\n\n    grid-template-columns:\n        repeat(2,minmax(0,1fr));\n\n    gap:9px;\n}\n\n\n/* =========================================================\n   NOTICE\n========================================================= */\n\n.gr-notice{\n    margin-top:15px;\n\n    padding:12px;\n\n    border-radius:10px;\n\n    background:#f5f0e8;\n\n    color:#71665c;\n\n    font-size:12px;\n}\n\n\n/* =========================================================\n   UTIL\n========================================================= */\n\n.gr-hidden{\n    display:none !important;\n}\n\n\n/* =========================================================\n   MOBILE\n========================================================= */\n\n@media(max-width:760px){\n\n    #ocdGraduationResultPage{\n        padding-left:8px;\n        padding-right:8px;\n    }\n\n    .gr-hero{\n        padding:27px 15px;\n    }\n\n    .gr-hero h1{\n        font-size:27px;\n    }\n\n    .gr-card{\n        padding:15px;\n    }\n\n    .gr-search-row{\n        display:grid;\n\n        grid-template-columns:1fr;\n    }\n\n    .gr-profile-grid{\n        grid-template-columns:\n            repeat(2,minmax(0,1fr));\n    }\n\n    .gr-score-grid{\n        grid-template-columns:1fr;\n    }\n\n    .gr-practical-grid{\n        grid-template-columns:1fr;\n    }\n\n    .gr-final-score{\n        font-size:47px;\n    }\n\n}\n\n@media(max-width:440px){\n\n    .gr-profile-grid{\n        grid-template-columns:1fr;\n    }\n\n    .gr-examiner-grid{\n        grid-template-columns:1fr;\n    }\n\n}\n\n</style>\n\n\n<!-- =========================================================\n     HERO\n========================================================= -->\n\n<section class=\"gr-hero\">\n\n    <div class=\"gr-hero-badge\">\n        K\u1ebeT QU\u1ea2 T\u1ed0T NGHI\u1ec6P OCD\n    </div>\n\n    <h1>\n        Tra c\u1ee9u k\u1ebft qu\u1ea3 t\u1ed1t nghi\u1ec7p\n    </h1>\n\n    <p>\n        H\u1ecdc vi\u00ean tra c\u1ee9u k\u1ebft qu\u1ea3 k\u1ef3 thi t\u1ed1t nghi\u1ec7p,\n        \u0111i\u1ec3m l\u00fd thuy\u1ebft, \u0111i\u1ec3m th\u1ef1c h\u00e0nh v\u00e0 nh\u1eadn x\u00e9t\n        c\u1ee7a gi\u00e1o vi\u00ean ch\u1ea5m thi.\n    </p>\n\n    <div class=\"gr-rule\">\n        L\u00fd thuy\u1ebft 50% + Th\u1ef1c h\u00e0nh 50% - \u0110\u1ea1t t\u1eeb 7 \u0111i\u1ec3m\n    </div>\n\n</section>\n\n\n<!-- =========================================================\n     LOOKUP\n========================================================= -->\n\n<section\n    class=\"gr-card\"\n    id=\"grLookupPanel\"\n>\n\n    <h2 class=\"gr-card-title\">\n        Tra c\u1ee9u h\u1ecdc vi\u00ean\n    </h2>\n\n    <div class=\"gr-search-row\">\n\n        <input\n            class=\"gr-input\"\n            id=\"grLookupInput\"\n            type=\"text\"\n            autocomplete=\"off\"\n            placeholder=\"Nh\u1eadp m\u00e3 h\u1ecdc vi\u00ean ho\u1eb7c Exam ID\"\n            onkeydown=\"\n                if(event.key==='Enter'){\n                    event.preventDefault();\n                    return window.OCDGraduationResult.lookup();\n                }\n            \"\n        >\n\n        <button\n            class=\"gr-btn\"\n            id=\"grLookupButton\"\n            type=\"button\"\n            onclick=\"return window.OCDGraduationResult.lookup();\"\n        >\n            TRA C\u1ee8U\n        </button>\n\n    </div>\n\n    <div\n        class=\"gr-message\"\n        id=\"grMessage\"\n    ></div>\n\n    <div\n        class=\"gr-attempt-list gr-hidden\"\n        id=\"grAttemptList\"\n    ></div>\n\n</section>\n\n\n<!-- =========================================================\n     RESULT\n========================================================= -->\n\n<section\n    class=\"gr-card gr-hidden\"\n    id=\"grResultPanel\"\n>\n\n    <div id=\"grResultContent\"></div>\n\n</section>\n\n\n<script>\n/* =========================================================\n   OCD GRADUATION RESULT\n   v1.0\n========================================================= */\n\nwindow.OCDGraduationResult =\nwindow.OCDGraduationResult || {};\n\n\n(function(APP){\n\n\"use strict\";\n\n\n/* =========================================================\n   CONFIG\n========================================================= */\n\nvar CONFIG={\n\n    version:\n        \"OCD_GRADUATION_RESULT_V1.0\",\n\n    spreadsheetId:\n        \"1GJoTRsbq0kZfZrDdh0uCC667PwS3Bgkje2fHQnwnCKs\",\n\n    examSheet:\n        \"BaiThiTotNghiep\",\n\n    gradingSheet:\n        \"ChamThiTotNghiep\",\n\n    passScore:\n        7,\n\n    theoryWeight:\n        0.5,\n\n    practicalWeight:\n        0.5,\n\n    timeout:\n        15000,\n\n    lastLookupKey:\n        \"OCD_GRADUATION_RESULT_LAST_LOOKUP\"\n\n};\n\n\n/* =========================================================\n   STATE\n========================================================= */\n\nvar STATE={\n\n    exams:[],\n\n    gradings:[],\n\n    matches:[],\n\n    attemptRenderMap:{},\n\n    selectedExam:null,\n\n    selectedGrading:null\n\n};\n\n\n/* =========================================================\n   DOM\n========================================================= */\n\nfunction el(id){\n\n    return document.getElementById(id);\n}\n\n\n/* =========================================================\n   NORMALIZE\n========================================================= */\n\nfunction normalizeText(value){\n\n    return String(\n        value===undefined ||\n        value===null\n            ?\n            \"\"\n            :\n            value\n    )\n    .trim()\n    .toLowerCase()\n    .normalize(\"NFD\")\n    .replace(/[\\u0300-\\u036f]/g,\"\")\n    .replace(/\u0111/g,\"d\")\n    .replace(/\\s+/g,\" \");\n}\n\n\nfunction normalizeCode(value){\n\n    return String(\n        value===undefined ||\n        value===null\n            ?\n            \"\"\n            :\n            value\n    )\n    .trim()\n    .toUpperCase();\n}\n\n\n/* =========================================================\n   ESCAPE\n========================================================= */\n\nfunction escapeHtml(value){\n\n    return String(\n        value===undefined ||\n        value===null\n            ?\n            \"\"\n            :\n            value\n    )\n    .replace(/&/g,\"&amp;\")\n    .replace(/</g,\"&lt;\")\n    .replace(/>/g,\"&gt;\")\n    .replace(/\"/g,\"&quot;\")\n    .replace(/'/g,\"&#39;\");\n}\n\n\n/* =========================================================\n   CSV\n========================================================= */\n\nfunction parseCSV(text){\n\n    var rows=[];\n    var row=[];\n    var field=\"\";\n    var quoted=false;\n\n\n    text=\n        String(text || \"\")\n        .replace(/^\\uFEFF/,\"\");\n\n\n    for(\n        var i=0;\n        i<text.length;\n        i++\n    ){\n\n        var c=\n            text[i];\n\n\n        if(c==='\"'){\n\n            if(\n                quoted &&\n                text[i+1]==='\"'\n            ){\n\n                field+='\"';\n\n                i++;\n\n            }else{\n\n                quoted=\n                    !quoted;\n            }\n\n        }else if(\n            c===\",\" &&\n            !quoted\n        ){\n\n            row.push(field);\n\n            field=\"\";\n\n        }else if(\n            (\n                c===\"\\n\" ||\n                c===\"\\r\"\n            ) &&\n            !quoted\n        ){\n\n            if(\n                c===\"\\r\" &&\n                text[i+1]===\"\\n\"\n            ){\n\n                i++;\n            }\n\n\n            row.push(field);\n\n\n            if(\n                row.some(\n                    function(v){\n\n                        return (\n                            String(v)\n                            .trim()!==\"\"\n                        );\n                    }\n                )\n            ){\n\n                rows.push(row);\n            }\n\n\n            row=[];\n\n            field=\"\";\n\n        }else{\n\n            field+=c;\n        }\n    }\n\n\n    row.push(field);\n\n\n    if(\n        row.some(\n            function(v){\n\n                return (\n                    String(v)\n                    .trim()!==\"\"\n                );\n            }\n        )\n    ){\n\n        rows.push(row);\n    }\n\n\n    return rows;\n}\n\n\n/* =========================================================\n   FETCH\n========================================================= */\n\nfunction sheetUrl(sheetName){\n\n    return (\n        \"https://docs.google.com/spreadsheets/d/\" +\n        CONFIG.spreadsheetId +\n        \"/gviz/tq?tqx=out:csv&sheet=\" +\n        encodeURIComponent(\n            sheetName\n        ) +\n        \"&_=\" +\n        Date.now()\n    );\n}\n\n\nfunction fetchWithTimeout(url){\n\n    var controller=\n        typeof AbortController!==\"undefined\"\n            ?\n            new AbortController()\n            :\n            null;\n\n\n    var timer=\n        controller\n            ?\n            setTimeout(\n                function(){\n\n                    controller.abort();\n\n                },\n                CONFIG.timeout\n            )\n            :\n            null;\n\n\n    return fetch(\n        url,\n        {\n            cache:\"no-store\",\n\n            signal:\n                controller\n                    ?\n                    controller.signal\n                    :\n                    undefined\n        }\n    )\n\n    .then(\n        function(response){\n\n            if(!response.ok){\n\n                throw new Error(\n                    \"HTTP \" +\n                    response.status\n                );\n            }\n\n\n            return response.text();\n        }\n    )\n\n    .finally(\n        function(){\n\n            if(timer){\n\n                clearTimeout(timer);\n            }\n        }\n    );\n}\n\n\nfunction sleep(ms){\n\n    return new Promise(\n        function(resolve){\n\n            setTimeout(\n                resolve,\n                ms\n            );\n        }\n    );\n}\n\n\nasync function fetchRetry(url){\n\n    var lastError=null;\n\n\n    for(\n        var i=0;\n        i<2;\n        i++\n    ){\n\n        try{\n\n            return await fetchWithTimeout(\n                url\n            );\n\n        }catch(error){\n\n            lastError=\n                error;\n\n\n            if(i===0){\n\n                await sleep(\n                    400\n                );\n            }\n        }\n    }\n\n\n    throw lastError;\n}\n\n\n/* =========================================================\n   COLUMN\n========================================================= */\n\nfunction findColumn(\n    headers,\n    aliases\n){\n\n    var normalized=\n        headers.map(\n            normalizeText\n        );\n\n\n    for(\n        var i=0;\n        i<aliases.length;\n        i++\n    ){\n\n        var wanted=\n            normalizeText(\n                aliases[i]\n            );\n\n\n        var exact=\n            normalized.indexOf(\n                wanted\n            );\n\n\n        if(exact!==-1){\n\n            return exact;\n        }\n    }\n\n\n    for(\n        var a=0;\n        a<aliases.length;\n        a++\n    ){\n\n        var partial=\n            normalizeText(\n                aliases[a]\n            );\n\n\n        for(\n            var h=0;\n            h<normalized.length;\n            h++\n        ){\n\n            if(\n                partial &&\n                normalized[h]\n                .indexOf(\n                    partial\n                )!==-1\n            ){\n\n                return h;\n            }\n        }\n    }\n\n\n    return -1;\n}\n\n\nfunction valueAt(\n    row,\n    index\n){\n\n    if(\n        index<0 ||\n        !row ||\n        index>=row.length\n    ){\n\n        return \"\";\n    }\n\n\n    return String(\n        row[index] || \"\"\n    )\n    .trim();\n}\n\n\n/* =========================================================\n   NUMBER\n========================================================= */\n\nfunction parseNumber(value){\n\n    var str=\n        String(\n            value===undefined ||\n            value===null\n                ?\n                \"\"\n                :\n                value\n        )\n        .trim()\n        .replace(\n            \",\",\n            \".\"\n        );\n\n\n    if(str===\"\"){\n\n        return null;\n    }\n\n\n    var number=\n        Number(str);\n\n\n    return Number.isFinite(number)\n        ?\n        number\n        :\n        null;\n}\n\n\nfunction round2(value){\n\n    return Math.round(\n        Number(value) *\n        100\n    ) / 100;\n}\n\n\nfunction scoreDisplay(value){\n\n    var n=\n        parseNumber(value);\n\n\n    if(n===null){\n\n        return \"-\";\n    }\n\n\n    return n.toFixed(2)\n        .replace(\n            /\\.00$/,\n            \"\"\n        )\n        .replace(\n            /(\\.\\d)0$/,\n            \"$1\"\n        );\n}\n\n\n/* =========================================================\n   DRIVE IMAGE\n========================================================= */\n\nfunction driveIdFromUrl(value){\n\n    var str=\n        String(\n            value || \"\"\n        )\n        .trim();\n\n\n    if(!str){\n\n        return \"\";\n    }\n\n\n    var patterns=[\n\n        /\\/file\\/d\\/([a-zA-Z0-9_-]+)/,\n\n        /[?&]id=([a-zA-Z0-9_-]+)/,\n\n        /\\/d\\/([a-zA-Z0-9_-]+)/\n    ];\n\n\n    for(\n        var i=0;\n        i<patterns.length;\n        i++\n    ){\n\n        var match=\n            str.match(\n                patterns[i]\n            );\n\n\n        if(match){\n\n            return match[1];\n        }\n    }\n\n\n    if(\n        /^[a-zA-Z0-9_-]{20,}$/\n        .test(str)\n    ){\n\n        return str;\n    }\n\n\n    return \"\";\n}\n\n\nfunction imageUrl(value){\n\n    var RS=\n        window.StudentRewardSystem;\n\n\n    if(\n        RS &&\n        typeof RS.convertDriveImageUrl===\n        \"function\"\n    ){\n\n        try{\n\n            return RS.convertDriveImageUrl(\n                value,\n                800\n            );\n\n        }catch(error){}\n    }\n\n\n    var id=\n        driveIdFromUrl(\n            value\n        );\n\n\n    if(id){\n\n        return (\n            \"https://drive.google.com/thumbnail?id=\" +\n            encodeURIComponent(id) +\n            \"&sz=w800\"\n        );\n    }\n\n\n    return String(\n        value || \"\"\n    );\n}\n\n\n/* =========================================================\n   MESSAGE\n========================================================= */\n\nfunction setMessage(\n    text,\n    type\n){\n\n    var box=\n        el(\n            \"grMessage\"\n        );\n\n\n    box.className=\n        \"gr-message show \" +\n        (\n            type ||\n            \"loading\"\n        );\n\n\n    box.textContent=\n        text;\n}\n\n\n/* =========================================================\n   LOAD EXAM SHEET\n========================================================= */\n\nasync function loadExams(){\n\n    var text=\n        await fetchRetry(\n            sheetUrl(\n                CONFIG.examSheet\n            )\n        );\n\n\n    var rows=\n        parseCSV(text);\n\n\n    if(\n        !rows ||\n        rows.length<2\n    ){\n\n        return [];\n    }\n\n\n    var headers=\n        rows[0];\n\n\n    var cols={\n\n        timestamp:\n            findColumn(\n                headers,\n                [\"D\u1ea5u th\u1eddi gian\"]\n            ),\n\n        examId:\n            findColumn(\n                headers,\n                [\n                    \"Exam ID\",\n                    \"ExamID\"\n                ]\n            ),\n\n        code:\n            findColumn(\n                headers,\n                [\"M\u00e3 h\u1ecdc vi\u00ean\"]\n            ),\n\n        name:\n            findColumn(\n                headers,\n                [\"H\u1ecd v\u00e0 t\u00ean\"]\n            ),\n\n        group:\n            findColumn(\n                headers,\n                [\"T\u1ed5\"]\n            ),\n\n        course:\n            findColumn(\n                headers,\n                [\n                    \"Kho\u00e1\",\n                    \"Kh\u00f3a\"\n                ]\n            ),\n\n        startedAt:\n            findColumn(\n                headers,\n                [\"Th\u1eddi gian b\u1eaft \u0111\u1ea7u\"]\n            ),\n\n        submittedAt:\n            findColumn(\n                headers,\n                [\"Th\u1eddi gian n\u1ed9p\"]\n            ),\n\n        submitReason:\n            findColumn(\n                headers,\n                [\"H\u00ecnh th\u1ee9c n\u1ed9p\"]\n            ),\n\n        theoryAnswered:\n            findColumn(\n                headers,\n                [\"S\u1ed1 c\u00e2u l\u00fd thuy\u1ebft \u0111\u00e3 l\u00e0m\"]\n            ),\n\n        theoryCorrect:\n            findColumn(\n                headers,\n                [\"S\u1ed1 c\u00e2u l\u00fd thuy\u1ebft \u0111\u00fang\"]\n            ),\n\n        theoryWrong:\n            findColumn(\n                headers,\n                [\"S\u1ed1 c\u00e2u l\u00fd thuy\u1ebft sai\"]\n            ),\n\n        theoryScore:\n            findColumn(\n                headers,\n                [\"\u0110i\u1ec3m l\u00fd thuy\u1ebft\"]\n            ),\n\n        practicalAnswered:\n            findColumn(\n                headers,\n                [\"S\u1ed1 c\u00e2u th\u1ef1c h\u00e0nh \u0111\u00e3 ch\u1ecdn\"]\n            ),\n\n        practicalData:\n            findColumn(\n                headers,\n                [\"PracticalData\"]\n            ),\n\n        version:\n            findColumn(\n                headers,\n                [\"Phi\u00ean b\u1ea3n h\u1ec7 th\u1ed1ng\"]\n            )\n    };\n\n\n    if(\n        cols.examId<0 ||\n        cols.code<0\n    ){\n\n        throw new Error(\n            \"Kh\u00f4ng nh\u1eadn di\u1ec7n \u0111\u01b0\u1ee3c c\u1ea5u tr\u00fac BaiThiTotNghiep.\"\n        );\n    }\n\n\n    var result=[];\n\n\n    for(\n        var i=1;\n        i<rows.length;\n        i++\n    ){\n\n        var row=\n            rows[i];\n\n\n        var examId=\n            valueAt(\n                row,\n                cols.examId\n            );\n\n\n        if(!examId){\n\n            continue;\n        }\n\n\n        result.push({\n\n            rowNumber:\n                i+1,\n\n            timestamp:\n                valueAt(\n                    row,\n                    cols.timestamp\n                ),\n\n            examId:\n                examId,\n\n            studentCode:\n                normalizeCode(\n                    valueAt(\n                        row,\n                        cols.code\n                    )\n                ),\n\n            studentName:\n                valueAt(\n                    row,\n                    cols.name\n                ),\n\n            group:\n                valueAt(\n                    row,\n                    cols.group\n                ),\n\n            course:\n                valueAt(\n                    row,\n                    cols.course\n                ),\n\n            startedAt:\n                valueAt(\n                    row,\n                    cols.startedAt\n                ),\n\n            submittedAt:\n                valueAt(\n                    row,\n                    cols.submittedAt\n                ),\n\n            submitReason:\n                valueAt(\n                    row,\n                    cols.submitReason\n                ),\n\n            theoryAnswered:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.theoryAnswered\n                    )\n                ) || 0,\n\n            theoryCorrect:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.theoryCorrect\n                    )\n                ) || 0,\n\n            theoryWrong:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.theoryWrong\n                    )\n                ) || 0,\n\n            theoryScore:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.theoryScore\n                    )\n                ),\n\n            practicalAnswered:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.practicalAnswered\n                    )\n                ) || 0,\n\n            practicalRaw:\n                valueAt(\n                    row,\n                    cols.practicalData\n                ),\n\n            version:\n                valueAt(\n                    row,\n                    cols.version\n                )\n        });\n    }\n\n\n    return result;\n}\n\n\n/* =========================================================\n   LOAD GRADING SHEET\n========================================================= */\n\nasync function loadGradings(){\n\n    var text=\n        await fetchRetry(\n            sheetUrl(\n                CONFIG.gradingSheet\n            )\n        );\n\n\n    var rows=\n        parseCSV(text);\n\n\n    /*\n       Tab m\u1edbi c\u00f3 th\u1ec3 ch\u1ec9 c\u00f3 header.\n       Tr\u01b0\u1eddng h\u1ee3p n\u00e0y KH\u00d4NG ph\u1ea3i l\u1ed7i.\n    */\n\n    if(\n        !rows ||\n        rows.length<1\n    ){\n\n        return [];\n    }\n\n\n    var headers=\n        rows[0];\n\n\n    var cols={\n\n        timestamp:\n            findColumn(\n                headers,\n                [\"D\u1ea5u th\u1eddi gian\"]\n            ),\n\n        examId:\n            findColumn(\n                headers,\n                [\n                    \"Exam ID\",\n                    \"ExamID\"\n                ]\n            ),\n\n        code:\n            findColumn(\n                headers,\n                [\"M\u00e3 h\u1ecdc vi\u00ean\"]\n            ),\n\n        name:\n            findColumn(\n                headers,\n                [\"H\u1ecd v\u00e0 t\u00ean\"]\n            ),\n\n        group:\n            findColumn(\n                headers,\n                [\"T\u1ed5\"]\n            ),\n\n        course:\n            findColumn(\n                headers,\n                [\n                    \"Kho\u00e1\",\n                    \"Kh\u00f3a\"\n                ]\n            ),\n\n        theoryScore:\n            findColumn(\n                headers,\n                [\"\u0110i\u1ec3m l\u00fd thuy\u1ebft\"]\n            ),\n\n        practicalScore:\n            findColumn(\n                headers,\n                [\"\u0110i\u1ec3m th\u1ef1c h\u00e0nh\"]\n            ),\n\n        practicalGraded:\n            findColumn(\n                headers,\n                [\n                    \"S\u1ed1 c\u00e2u \u0111\u00e3 ch\u1ea5m\",\n                    \"S\u1ed1 c\u00e2u th\u1ef1c h\u00e0nh \u0111\u00e3 ch\u1ea5m\"\n                ]\n            ),\n\n        gradingData:\n            findColumn(\n                headers,\n                [\"GradingData\"]\n            ),\n\n        examiner:\n            findColumn(\n                headers,\n                [\"Ng\u01b0\u1eddi ch\u1ea5m\"]\n            ),\n\n        gradedAt:\n            findColumn(\n                headers,\n                [\"Th\u1eddi gian ch\u1ea5m\"]\n            ),\n\n        version:\n            findColumn(\n                headers,\n                [\"Phi\u00ean b\u1ea3n h\u1ec7 th\u1ed1ng\"]\n            )\n    };\n\n\n    if(\n        cols.examId<0\n    ){\n\n        throw new Error(\n            \"Kh\u00f4ng nh\u1eadn di\u1ec7n \u0111\u01b0\u1ee3c c\u1ea5u tr\u00fac ChamThiTotNghiep.\"\n        );\n    }\n\n\n    var result=[];\n\n\n    for(\n        var i=1;\n        i<rows.length;\n        i++\n    ){\n\n        var row=\n            rows[i];\n\n\n        var examId=\n            valueAt(\n                row,\n                cols.examId\n            );\n\n\n        if(!examId){\n\n            continue;\n        }\n\n\n        result.push({\n\n            rowNumber:\n                i+1,\n\n            timestamp:\n                valueAt(\n                    row,\n                    cols.timestamp\n                ),\n\n            examId:\n                examId,\n\n            studentCode:\n                normalizeCode(\n                    valueAt(\n                        row,\n                        cols.code\n                    )\n                ),\n\n            studentName:\n                valueAt(\n                    row,\n                    cols.name\n                ),\n\n            group:\n                valueAt(\n                    row,\n                    cols.group\n                ),\n\n            course:\n                valueAt(\n                    row,\n                    cols.course\n                ),\n\n            theoryScore:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.theoryScore\n                    )\n                ),\n\n            practicalScore:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.practicalScore\n                    )\n                ),\n\n            practicalGraded:\n                parseNumber(\n                    valueAt(\n                        row,\n                        cols.practicalGraded\n                    )\n                ) || 0,\n\n            gradingRaw:\n                valueAt(\n                    row,\n                    cols.gradingData\n                ),\n\n            examiner:\n                valueAt(\n                    row,\n                    cols.examiner\n                ),\n\n            gradedAt:\n                valueAt(\n                    row,\n                    cols.gradedAt\n                ),\n\n            version:\n                valueAt(\n                    row,\n                    cols.version\n                )\n        });\n    }\n\n\n    return result;\n}\n\n\n/* =========================================================\n   GRADING MAP\n\n   N\u1ebfu m\u1ed9t Exam ID c\u00f3 nhi\u1ec1u b\u1ea3n ch\u1ea5m,\n   \u01b0u ti\u00ean d\u00f2ng M\u1edaI NH\u1ea4T trong Sheet.\n========================================================= */\n\nfunction buildGradingMap(gradings){\n\n    var map={};\n\n\n    gradings.forEach(\n        function(item){\n\n            map[\n                normalizeCode(\n                    item.examId\n                )\n            ]=\n                item;\n        }\n    );\n\n\n    return map;\n}\n\n\n/* =========================================================\n   LOOKUP\n========================================================= */\n\nAPP.lookup=\nasync function(){\n\n    var input=\n        el(\n            \"grLookupInput\"\n        );\n\n\n    var button=\n        el(\n            \"grLookupButton\"\n        );\n\n\n    var query=\n        String(\n            input.value ||\n            \"\"\n        )\n        .trim();\n\n\n    if(!query){\n\n        setMessage(\n            \"Vui l\u00f2ng nh\u1eadp m\u00e3 h\u1ecdc vi\u00ean ho\u1eb7c Exam ID.\",\n            \"error\"\n        );\n\n\n        return false;\n    }\n\n\n    try{\n\n        localStorage.setItem(\n            CONFIG.lastLookupKey,\n            query\n        );\n\n    }catch(error){}\n\n\n    button.disabled=\n        true;\n\n\n    button.textContent=\n        \"\u0110ANG TRA C\u1ee8U...\";\n\n\n    setMessage(\n        \"\u0110ang \u0111\u1ecdc d\u1eef li\u1ec7u b\u00e0i thi v\u00e0 k\u1ebft qu\u1ea3 ch\u1ea5m...\",\n        \"loading\"\n    );\n\n\n    el(\n        \"grAttemptList\"\n    )\n    .classList\n    .add(\n        \"gr-hidden\"\n    );\n\n\n    el(\n        \"grResultPanel\"\n    )\n    .classList\n    .add(\n        \"gr-hidden\"\n    );\n\n\n    try{\n\n        /*\n         \u0110\u1ecdc song song 2 tab \u0111\u1ec3 nhanh h\u01a1n.\n        */\n\n        var data=\n            await Promise.all([\n\n                loadExams(),\n\n                loadGradings()\n\n            ]);\n\n\n        STATE.exams=\n            data[0];\n\n\n        STATE.gradings=\n            data[1];\n\n\n        var wanted=\n            normalizeCode(\n                query\n            );\n\n\n        var matches=\n            STATE.exams.filter(\n                function(exam){\n\n                    return (\n                        normalizeCode(\n                            exam.studentCode\n                        )===\n                        wanted\n                    ) ||\n                    (\n                        normalizeCode(\n                            exam.examId\n                        )===\n                        wanted\n                    );\n                }\n            );\n\n\n        if(!matches.length){\n\n            throw new Error(\n                \"Kh\u00f4ng t\u00ecm th\u1ea5y b\u00e0i thi c\u1ee7a h\u1ecdc vi\u00ean.\"\n            );\n        }\n\n\n        var gradingMap=\n            buildGradingMap(\n                STATE.gradings\n            );\n\n\n        STATE.matches=\n            matches.map(\n                function(exam){\n\n                    return {\n\n                        exam:\n                            exam,\n\n                        grading:\n                            gradingMap[\n                                normalizeCode(\n                                    exam.examId\n                                )\n                            ] ||\n                            null\n                    };\n                }\n            );\n\n\n        /*\n         M\u1ed9t Exam ID c\u1ee5 th\u1ec3\n         ho\u1eb7c ch\u1ec9 c\u00f3 1 l\u01b0\u1ee3t thi:\n         m\u1edf th\u1eb3ng k\u1ebft qu\u1ea3.\n        */\n\n        if(\n            STATE.matches.length===1\n        ){\n\n            openMatch(\n                STATE.matches[0]\n            );\n\n\n            setMessage(\n                STATE.matches[0].grading\n                    ?\n                    \"\u0110\u00e3 t\u1ea3i k\u1ebft qu\u1ea3 t\u1ed1t nghi\u1ec7p.\"\n                    :\n                    \"\u0110\u00e3 t\u00ecm th\u1ea5y b\u00e0i thi. K\u1ebft qu\u1ea3 \u0111ang ch\u1edd gi\u00e1o vi\u00ean ch\u1ea5m.\",\n                \"success\"\n            );\n\n\n        }else{\n\n            renderAttemptList();\n\n\n            setMessage(\n                \"T\u00ecm th\u1ea5y \" +\n                STATE.matches.length +\n                \" l\u01b0\u1ee3t thi. H\u00e3y ch\u1ecdn \u0111\u00fang l\u01b0\u1ee3t c\u1ea7n xem.\",\n                \"success\"\n            );\n        }\n\n\n    }catch(error){\n\n        console.error(\n            error\n        );\n\n\n        setMessage(\n            error &&\n            error.message\n                ?\n                error.message\n                :\n                \"Kh\u00f4ng th\u1ec3 t\u1ea3i d\u1eef li\u1ec7u k\u1ebft qu\u1ea3.\",\n            \"error\"\n        );\n\n\n    }finally{\n\n        button.disabled=\n            false;\n\n\n        button.textContent=\n            \"TRA C\u1ee8U\";\n    }\n\n\n    return false;\n};\n\n\n/* =========================================================\n   ATTEMPT LIST\n========================================================= */\n\nfunction renderAttemptList(){\n\n    var box=\n        el(\n            \"grAttemptList\"\n        );\n\n\n    STATE.attemptRenderMap={};\n\n\n    var list=\n        STATE.matches\n        .slice()\n        .reverse();\n\n\n    var html=\"\";\n\n\n    list.forEach(\n        function(match,index){\n\n            STATE.attemptRenderMap[\n                String(index)\n            ]=\n                match;\n\n\n            var exam=\n                match.exam;\n\n\n            var grading=\n                match.grading;\n\n\n            var finalScore=\n                grading\n                    ?\n                    calculateFinalScore(\n                        exam,\n                        grading\n                    )\n                    :\n                    null;\n\n\n            html+=\n\n                '<div class=\"gr-attempt\">' +\n\n                    '<div>' +\n\n                        '<div class=\"gr-attempt-name\">' +\n                            escapeHtml(\n                                exam.studentName ||\n                                exam.studentCode\n                            ) +\n                        '</div>' +\n\n                        '<div class=\"gr-attempt-meta\">' +\n\n                            'Exam ID: ' +\n                            escapeHtml(\n                                exam.examId\n                            ) +\n\n                            '<br>' +\n\n                            'N\u1ed9p b\u00e0i: ' +\n                            escapeHtml(\n                                exam.submittedAt ||\n                                exam.timestamp ||\n                                \"-\"\n                            ) +\n\n                        '</div>';\n\n\n            if(grading){\n\n                html+=\n\n                    '<div class=\"gr-attempt-status graded\">' +\n\n                        '\u0110\u00c3 CH\u1ea4M' +\n\n                        (\n                            finalScore!==null\n                                ?\n                                ' - ' +\n                                scoreDisplay(\n                                    finalScore\n                                ) +\n                                ' \u0110I\u1ec2M'\n                                :\n                                ''\n                        ) +\n\n                    '</div>';\n\n            }else{\n\n                html+=\n\n                    '<div class=\"gr-attempt-status waiting\">' +\n                        '\u0110ANG CH\u1edc CH\u1ea4M' +\n                    '</div>';\n            }\n\n\n            html+=\n\n                    '</div>' +\n\n                    '<button ' +\n                        'class=\"gr-btn\" ' +\n                        'type=\"button\" ' +\n                        'onclick=\"return window.OCDGraduationResult.openAttempt(' +\n                            index +\n                        ');\">' +\n\n                        'XEM K\u1ebeT QU\u1ea2' +\n\n                    '</button>' +\n\n                '</div>';\n        }\n    );\n\n\n    box.innerHTML=\n        html;\n\n\n    box.classList\n    .remove(\n        \"gr-hidden\"\n    );\n}\n\n\nAPP.openAttempt=\nfunction(index){\n\n    var match=\n        STATE.attemptRenderMap[\n            String(index)\n        ];\n\n\n    if(match){\n\n        openMatch(\n            match\n        );\n    }\n\n\n    return false;\n};\n\n\n/* =========================================================\n   OPEN MATCH\n========================================================= */\n\nfunction openMatch(match){\n\n    STATE.selectedExam=\n        match.exam;\n\n\n    STATE.selectedGrading=\n        match.grading;\n\n\n    el(\n        \"grAttemptList\"\n    )\n    .classList\n    .add(\n        \"gr-hidden\"\n    );\n\n\n    el(\n        \"grResultPanel\"\n    )\n    .classList\n    .remove(\n        \"gr-hidden\"\n    );\n\n\n    renderResult();\n\n\n    try{\n\n        window.scrollTo({\n\n            top:\n                el(\n                    \"grResultPanel\"\n                ).offsetTop-20,\n\n            behavior:\n                \"smooth\"\n\n        });\n\n    }catch(error){}\n}\n\n\n/* =========================================================\n   INFO BOX\n========================================================= */\n\nfunction infoBox(\n    label,\n    value\n){\n\n    return (\n\n        '<div class=\"gr-info\">' +\n\n            '<div class=\"gr-info-label\">' +\n                escapeHtml(\n                    label\n                ) +\n            '</div>' +\n\n            '<div class=\"gr-info-value\">' +\n                escapeHtml(\n                    value===undefined ||\n                    value===null ||\n                    value===\"\"\n                        ?\n                        \"-\"\n                        :\n                        value\n                ) +\n            '</div>' +\n\n        '</div>'\n    );\n}\n\n\n/* =========================================================\n   FINAL SCORE\n\n   50% LT + 50% TH\n========================================================= */\n\nfunction calculateFinalScore(\n    exam,\n    grading\n){\n\n    if(\n        !exam ||\n        !grading\n    ){\n\n        return null;\n    }\n\n\n    /*\n       \u0110i\u1ec3m LT ch\u00ednh th\u1ee9c l\u1ea5y t\u1eeb b\u00e0i thi g\u1ed1c.\n       \u0110i\u1ec3m TH ch\u00ednh th\u1ee9c l\u1ea5y t\u1eeb b\u1ea3n GVCN ch\u1ea5m.\n    */\n\n    var theory=\n        parseNumber(\n            exam.theoryScore\n        );\n\n\n    var practical=\n        parseNumber(\n            grading.practicalScore\n        );\n\n\n    if(\n        theory===null ||\n        practical===null\n    ){\n\n        return null;\n    }\n\n\n    return round2(\n\n        theory *\n        CONFIG.theoryWeight +\n\n        practical *\n        CONFIG.practicalWeight\n\n    );\n}\n\n\n/* =========================================================\n   GRADING DATA\n========================================================= */\n\nfunction parseGradingData(raw){\n\n    if(!raw){\n\n        return [];\n    }\n\n\n    try{\n\n        var data=\n            JSON.parse(raw);\n\n\n        if(\n            !Array.isArray(\n                data\n            )\n        ){\n\n            return [];\n        }\n\n\n        return data\n            .filter(\n                function(item){\n\n                    return (\n                        item &&\n                        typeof item===\n                        \"object\"\n                    );\n                }\n            )\n            .sort(\n                function(a,b){\n\n                    return (\n                        Number(\n                            a.questionId ||\n                            a.q ||\n                            0\n                        ) -\n                        Number(\n                            b.questionId ||\n                            b.q ||\n                            0\n                        )\n                    );\n                }\n            );\n\n\n    }catch(error){\n\n        console.error(\n            \"GradingData JSON l\u1ed7i:\",\n            error\n        );\n\n\n        return [];\n    }\n}\n\n\n/* =========================================================\n   RESULT\n========================================================= */\n\nfunction renderResult(){\n\n    var exam=\n        STATE.selectedExam;\n\n\n    var grading=\n        STATE.selectedGrading;\n\n\n    if(!exam){\n\n        return;\n    }\n\n\n    var html=\n\n        '<h2 class=\"gr-card-title\">' +\n            'H\u1ed3 s\u01a1 k\u1ef3 thi' +\n        '</h2>' +\n\n\n        '<div class=\"gr-profile-grid\">' +\n\n            infoBox(\n                \"H\u1ecdc vi\u00ean\",\n                exam.studentName\n            ) +\n\n            infoBox(\n                \"M\u00e3 h\u1ecdc vi\u00ean\",\n                exam.studentCode\n            ) +\n\n            infoBox(\n                \"T\u1ed5\",\n                exam.group\n            ) +\n\n            infoBox(\n                \"Kh\u00f3a\",\n                exam.course\n            ) +\n\n            infoBox(\n                \"Exam ID\",\n                exam.examId\n            ) +\n\n            infoBox(\n                \"B\u1eaft \u0111\u1ea7u\",\n                exam.startedAt\n            ) +\n\n            infoBox(\n                \"N\u1ed9p b\u00e0i\",\n                exam.submittedAt\n            ) +\n\n            infoBox(\n                \"H\u00ecnh th\u1ee9c n\u1ed9p\",\n                exam.submitReason\n            ) +\n\n        '</div>';\n\n\n    /* =====================================================\n       CH\u01afA CH\u1ea4M\n    ===================================================== */\n\n    if(!grading){\n\n        html+=\n\n            '<div class=\"gr-waiting\">' +\n\n                '<div class=\"gr-waiting-icon\">' +\n                    String.fromCodePoint(\n                        9203\n                    ) +\n                '</div>' +\n\n                '<div class=\"gr-waiting-title\">' +\n                    '\u0110ang ch\u1edd ch\u1ea5m thi' +\n                '</div>' +\n\n                '<div class=\"gr-waiting-text\">' +\n\n                    'B\u00e0i thi \u0111\u00e3 \u0111\u01b0\u1ee3c h\u1ec7 th\u1ed1ng ti\u1ebfp nh\u1eadn nh\u01b0ng ch\u01b0a c\u00f3 ' +\n                    'k\u1ebft qu\u1ea3 ch\u1ea5m ph\u1ea7n th\u1ef1c h\u00e0nh t\u1eeb gi\u00e1o vi\u00ean.' +\n\n                    '<br>' +\n\n                    '\u0110i\u1ec3m l\u00fd thuy\u1ebft hi\u1ec7n t\u1ea1i: ' +\n                    '<strong>' +\n                        escapeHtml(\n                            scoreDisplay(\n                                exam.theoryScore\n                            )\n                        ) +\n                    '/10</strong>' +\n\n                '</div>' +\n\n            '</div>';\n\n\n        html+=\n\n            '<div class=\"gr-notice\">' +\n\n                'K\u1ebft qu\u1ea3 t\u1ed1t nghi\u1ec7p ch\u1ec9 \u0111\u01b0\u1ee3c c\u00f4ng b\u1ed1 sau khi gi\u00e1o vi\u00ean ' +\n                'ho\u00e0n t\u1ea5t ch\u1ea5m to\u00e0n b\u1ed9 ph\u1ea7n th\u1ef1c h\u00e0nh.' +\n\n            '</div>';\n\n\n        el(\n            \"grResultContent\"\n        )\n        .innerHTML=\n            html;\n\n\n        return;\n    }\n\n\n    /* =====================================================\n       \u0110\u00c3 CH\u1ea4M\n    ===================================================== */\n\n    var theory=\n        parseNumber(\n            exam.theoryScore\n        );\n\n\n    var practical=\n        parseNumber(\n            grading.practicalScore\n        );\n\n\n    var finalScore=\n        calculateFinalScore(\n            exam,\n            grading\n        );\n\n\n    if(\n        theory===null ||\n        practical===null ||\n        finalScore===null\n    ){\n\n        html+=\n\n            '<div class=\"gr-message show error\">' +\n\n                'B\u1ea3n ch\u1ea5m ch\u01b0a c\u00f3 \u0111\u1ee7 d\u1eef li\u1ec7u \u0111i\u1ec3m \u0111\u1ec3 t\u00ednh k\u1ebft qu\u1ea3 t\u1ed1t nghi\u1ec7p.' +\n\n            '</div>';\n\n\n        el(\n            \"grResultContent\"\n        )\n        .innerHTML=\n            html;\n\n\n        return;\n    }\n\n\n    var passed=\n        finalScore>=\n        CONFIG.passScore;\n\n\n    html+=\n\n        '<div class=\"gr-result-hero ' +\n            (\n                passed\n                    ?\n                    'pass'\n                    :\n                    'fail'\n            ) +\n        '\">' +\n\n            '<div class=\"gr-result-icon\">' +\n\n                (\n                    passed\n                        ?\n                        String.fromCodePoint(\n                            10003\n                        )\n                        :\n                        String.fromCodePoint(\n                            10005\n                        )\n                ) +\n\n            '</div>' +\n\n            '<div class=\"gr-result-label\">' +\n                '\u0110I\u1ec2M T\u1ed0T NGHI\u1ec6P' +\n            '</div>' +\n\n            '<div class=\"gr-final-score\">' +\n                escapeHtml(\n                    finalScore.toFixed(2)\n                ) +\n            '</div>' +\n\n            '<div class=\"gr-final-status\">' +\n\n                (\n                    passed\n                        ?\n                        '\u0110\u1ea0T T\u1ed0T NGHI\u1ec6P'\n                        :\n                        'CH\u01afA \u0110\u1ea0T T\u1ed0T NGHI\u1ec6P'\n                ) +\n\n            '</div>' +\n\n        '</div>';\n\n\n    /* =====================================================\n       SCORE GRID\n    ===================================================== */\n\n    html+=\n\n        '<div class=\"gr-score-grid\">' +\n\n            '<div class=\"gr-score-box\">' +\n\n                '<div class=\"gr-score-number\">' +\n                    escapeHtml(\n                        scoreDisplay(\n                            theory\n                        )\n                    ) +\n                '</div>' +\n\n                '<div class=\"gr-score-label\">' +\n                    'L\u00dd THUY\u1ebeT - 50%' +\n                '</div>' +\n\n            '</div>' +\n\n\n            '<div class=\"gr-score-box\">' +\n\n                '<div class=\"gr-score-number\">' +\n                    escapeHtml(\n                        scoreDisplay(\n                            practical\n                        )\n                    ) +\n                '</div>' +\n\n                '<div class=\"gr-score-label\">' +\n                    'TH\u1ef0C H\u00c0NH - 50%' +\n                '</div>' +\n\n            '</div>' +\n\n\n            '<div class=\"gr-score-box\">' +\n\n                '<div class=\"gr-score-number\">' +\n                    escapeHtml(\n                        finalScore.toFixed(2)\n                    ) +\n                '</div>' +\n\n                '<div class=\"gr-score-label\">' +\n                    '\u0110I\u1ec2M T\u1ed0T NGHI\u1ec6P' +\n                '</div>' +\n\n            '</div>' +\n\n        '</div>';\n\n\n    html+=\n\n        '<div class=\"gr-formula\">' +\n\n            '<strong>C\u00e1ch t\u00ednh:</strong> ' +\n\n            scoreDisplay(\n                theory\n            ) +\n\n            ' \u00d7 50% + ' +\n\n            scoreDisplay(\n                practical\n            ) +\n\n            ' \u00d7 50% = ' +\n\n            '<strong>' +\n                finalScore.toFixed(2) +\n            '</strong>' +\n\n            '<br>' +\n\n            '\u0110i\u1ec1u ki\u1ec7n t\u1ed1t nghi\u1ec7p: \u0111i\u1ec3m t\u1ed5ng t\u1eeb ' +\n            CONFIG.passScore.toFixed(2) +\n            ' tr\u1edf l\u00ean.' +\n\n        '</div>';\n\n\n    /* =====================================================\n       EXAMINER\n    ===================================================== */\n\n    html+=\n\n        '<div class=\"gr-examiner\">' +\n\n            '<div class=\"gr-examiner-grid\">' +\n\n                infoBox(\n                    \"Ng\u01b0\u1eddi ch\u1ea5m\",\n                    grading.examiner\n                ) +\n\n                infoBox(\n                    \"Th\u1eddi gian ch\u1ea5m\",\n                    grading.gradedAt ||\n                    grading.timestamp\n                ) +\n\n            '</div>' +\n\n        '</div>';\n\n\n    /* =====================================================\n       PRACTICAL DETAIL\n    ===================================================== */\n\n    var details=\n        parseGradingData(\n            grading.gradingRaw\n        );\n\n\n    if(details.length){\n\n        html+=\n\n            '<div class=\"gr-section-head\">' +\n\n                '<h3 class=\"gr-section-title\">' +\n                    'Chi ti\u1ebft ph\u1ea7n th\u1ef1c h\u00e0nh' +\n                '</h3>' +\n\n                '<div style=\"font-size:12px;color:var(--muted);\">' +\n                    details.length +\n                    ' b\u00e0i' +\n                '</div>' +\n\n            '</div>' +\n\n\n            '<div class=\"gr-practical-grid\">';\n\n\n        details.forEach(\n            function(item){\n\n                var questionId=\n                    item.questionId ||\n                    item.q ||\n                    \"-\";\n\n\n                var img=\n                    imageUrl(\n                        item.file\n                    );\n\n\n                var originalScore=\n                    item.originalScore;\n\n\n                var examScore=\n                    item.examScore;\n\n\n                html+=\n\n                    '<article class=\"gr-practical\">' +\n\n\n                        '<div class=\"gr-practical-image-wrap\">';\n\n\n                if(img){\n\n                    html+=\n\n                        '<img ' +\n                            'class=\"gr-practical-image\" ' +\n                            'loading=\"lazy\" ' +\n                            'src=\"' +\n                                escapeHtml(\n                                    img\n                                ) +\n                            '\" ' +\n                            'alt=\"B\u00e0i th\u1ef1c h\u00e0nh\">';\n\n                }else{\n\n                    html+=\n\n                        '<div class=\"gr-no-image\">' +\n                            'Kh\u00f4ng c\u00f3 \u1ea3nh xem tr\u01b0\u1edbc' +\n                        '</div>';\n                }\n\n\n                html+=\n\n                        '</div>' +\n\n\n                        '<div class=\"gr-practical-body\">' +\n\n                            '<div class=\"gr-practical-question\">' +\n                                'C\u00c2U ' +\n                                escapeHtml(\n                                    questionId\n                                ) +\n                            '</div>' +\n\n                            '<div class=\"gr-practical-title\">' +\n                                escapeHtml(\n                                    item.prompt ||\n                                    item.note ||\n                                    \"B\u00e0i th\u1ef1c h\u00e0nh\"\n                                ) +\n                            '</div>';\n\n\n                if(\n                    item.note &&\n                    item.note!==\n                    item.prompt\n                ){\n\n                    html+=\n\n                        '<div class=\"gr-practical-note\">' +\n                            escapeHtml(\n                                item.note\n                            ) +\n                        '</div>';\n                }\n\n\n                html+=\n\n                    '<div class=\"gr-practical-scores\">' +\n\n                        '<div class=\"gr-small-score\">' +\n\n                            '<div class=\"gr-small-score-label\">' +\n                                '\u0110i\u1ec3m c\u0169' +\n                            '</div>' +\n\n                            '<div class=\"gr-small-score-value\">' +\n                                escapeHtml(\n                                    scoreDisplay(\n                                        originalScore\n                                    )\n                                ) +\n                            '</div>' +\n\n                        '</div>' +\n\n\n                        '<div class=\"gr-small-score\">' +\n\n                            '<div class=\"gr-small-score-label\">' +\n                                '\u0110i\u1ec3m thi' +\n                            '</div>' +\n\n                            '<div class=\"gr-small-score-value\">' +\n                                escapeHtml(\n                                    scoreDisplay(\n                                        examScore\n                                    )\n                                ) +\n                            '</div>' +\n\n                        '</div>' +\n\n                    '</div>';\n\n\n                if(\n                    item.examinerComment\n                ){\n\n                    html+=\n\n                        '<div class=\"gr-comment\">' +\n\n                            '<strong>Nh\u1eadn x\u00e9t:</strong><br>' +\n\n                            escapeHtml(\n                                item.examinerComment\n                            ) +\n\n                        '</div>';\n                }\n\n\n                if(\n                    item.usedOldScore\n                ){\n\n                    html+=\n\n                        '<div style=\"' +\n                            'margin-top:8px;' +\n                            'font-size:10px;' +\n                            'font-weight:900;' +\n                            'color:#7c642c;' +\n                        '\">' +\n\n                            'GI\u00c1O VI\u00caN GI\u1eee NGUY\u00caN \u0110I\u1ec2M C\u0168' +\n\n                        '</div>';\n                }\n\n\n                html+=\n\n                        '</div>' +\n\n                    '</article>';\n            }\n        );\n\n\n        html+=\n            '</div>';\n    }\n\n\n    html+=\n\n        '<div class=\"gr-notice\">' +\n\n            '\u0110i\u1ec3m b\u00e0i luy\u1ec7n t\u1eadp c\u0169 ch\u1ec9 c\u00f3 gi\u00e1 tr\u1ecb tham kh\u1ea3o. ' +\n            '\u0110i\u1ec3m th\u1ef1c h\u00e0nh t\u1ed1t nghi\u1ec7p \u0111\u01b0\u1ee3c l\u1ea5y t\u1eeb b\u1ea3n ch\u1ea5m c\u1ee7a gi\u00e1o vi\u00ean. ' +\n            'K\u1ebft qu\u1ea3 t\u1ed1t nghi\u1ec7p \u0111\u01b0\u1ee3c t\u00ednh theo t\u1ef7 tr\u1ecdng 50% l\u00fd thuy\u1ebft v\u00e0 50% th\u1ef1c h\u00e0nh.' +\n\n        '</div>';\n\n\n    el(\n        \"grResultContent\"\n    )\n    .innerHTML=\n        html;\n}\n\n\n/* =========================================================\n   INIT\n========================================================= */\n\nfunction init(){\n\n    try{\n\n        var last=\n            localStorage.getItem(\n                CONFIG.lastLookupKey\n            );\n\n\n        if(last){\n\n            el(\n                \"grLookupInput\"\n            )\n            .value=\n                last;\n        }\n\n    }catch(error){}\n\n\n    console.log(\n        CONFIG.version +\n        \" READY\"\n    );\n}\n\n\nif(\n    document.readyState===\n    \"loading\"\n){\n\n    document.addEventListener(\n        \"DOMContentLoaded\",\n        init\n    );\n\n}else{\n\n    init();\n}\n\n\n})(window.OCDGraduationResult);\n\n</script>\n\n</div>\n");})();
